        vm.stopBroadcast();
    }

    /// @notice Displayed native18 approval/pull; Q/q/B use exact internal ER shares.
    function surrenderEarlierReceipt(
        Migration proxy_, bytes32 originalId_, uint256 amount_, uint256 minimum_, uint256 deadline_
    ) external returns (uint256 bondTokenId_, uint256 credit_) {
        vm.startBroadcast(vm.envAddress("SENDER"));
        (bondTokenId_, credit_) = proxy_.surrenderMigrationEarlierReceipt(originalId_, amount_, minimum_, deadline_);
        vm.stopBroadcast();
    }

    /// @notice Genuine paid ordinary purchase, with explicit operator amounts and duration.
    function ownerFirstBond(Migration proxy_, IERC20 token_, uint256 amount_, uint256 duration_, uint256 deadline_)
        external returns (uint256 bondId_, uint256 lpOut_)
    {
        address sender_ = vm.envAddress("SENDER");
        vm.startBroadcast(sender_);
        require(token_.approve(address(proxy_), amount_), "purchase approval");
        (bondId_, lpOut_) = proxy_.bond(token_, amount_, duration_, sender_, false, deadline_);
        vm.stopBroadcast();
    }

    function harvest(Recovery proxy_, Recovery.Step[] calldata steps_, uint256 deadline_) external {
        vm.startBroadcast(vm.envAddress("SENDER"));
        proxy_.recoverMigrationNfts(steps_, deadline_);
        vm.stopBroadcast();
    }
}

import { Interface, Transaction, keccak256, toUtf8Bytes } from "ethers";
import type { JsonRpcProvider } from "ethers";
import { z } from "zod";
import { canonical } from "./provenance.js";
import { address, hash, hex, PreparationError } from "./schema.js";
import type { ClaimedSyCertificate, Domain, PreparationInput, WeightedSyOriginal } from "./schema.js";
import { stakingClaim, proxyHash, routes } from "./claimed-sy-source.js";
export { stakingSource, stakingClaim } from "./claimed-sy-source.js";
const quantity = z.string().regex(/^0x[0-9a-fA-F]+$/);
const block = z.object({ number: quantity, hash, parentHash: hash, transactions: z.array(hash) }).passthrough();
const callFrame = z.object({
  from: address, to: address, input: hex, output: hex.default("0x"), type: z.string(),
  error: z.string().optional(), calls: z.array(z.unknown()).default([]),
}).passthrough();
const log = z.object({
  address, topics: z.array(hash), data: hex, blockHash: hash, blockNumber: quantity,
  transactionHash: hash, transactionIndex: quantity, removed: z.literal(false),
}).passthrough();
const receipt = z.object({
  status: quantity, from: address, to: address, transactionHash: hash,
  blockHash: hash, blockNumber: quantity, transactionIndex: quantity, logs: z.array(log),
}).passthrough();
const transaction = z.object({
  hash, from: address, to: address, input: hex, value: quantity, chainId: quantity,
  blockHash: hash, blockNumber: quantity, transactionIndex: quantity,
}).passthrough();
function requireEvidence(valid: boolean, message: string): asserts valid {
  if (!valid) throw new PreparationError("PROVENANCE", `claimed SY: ${message}`);
}

export function claimedSyEvidenceId(domain: Domain, original: WeightedSyOriginal, certificate: ClaimedSyCertificate) {
  const { evidenceId: _commitment, ...inputs } = original;
  return keccak256(toUtf8Bytes(canonical({
    kind: "IndexedEx.complete-original-claimed-sy-v1",
    chainId: domain.chainId, proxy: domain.proxy, snapshotId: domain.snapshotId,
    original: inputs, certificate,
  })));
}

/** Historical review is explicit; no hash or current balance authenticates that review. */
export function validateClaimedSyInputs(input: PreparationInput): void {
  const members = new Set<string>();
  for (const row of input.weightedSy) {
    const c = row.claimedOrigin;
    if (!c) continue;
    const r = c.review;
    const o = row.original;
    switch (c.kind) {
      case "complete-original-token-staking":
        requireEvidence(r.originalWeight === undefined, "complete original cannot override its weight basis");
        break;
      case "complete-remaining-token-staking":
        requireEvidence(r.originalWeight !== undefined
          && BigInt(r.eligibleWeight) <= BigInt(r.originalWeight), "remaining weight exceeds or lacks full original weight");
        break;
      default: {
        const kind: never = c.kind;
        throw new PreparationError("PROVENANCE", kind);
      }
    }
    requireEvidence(input.domain.chainId === c.chainId && o.source === c.sy
      && r.originalId === o.originalId && r.originalWallet === o.originalWallet
      && r.originalEth === o.originalEth && r.originalDtf === o.originalDtf
      && o.contributionsKnown, "review and complete original differ");
    requireEvidence(c.members.reduce((sum, m) => sum + BigInt(m.consumedWeight), 0n) === BigInt(r.eligibleWeight),
      "incomplete or excess original weight coverage");
    const q0 = c.members.reduce((sum, m) => sum + BigInt(m.receivedSy), 0n);
    requireEvidence(q0 > 0n && q0 === BigInt(o.originalUnits), "measured original SY sum differs");
    for (const member of c.members) {
      requireEvidence(!members.has(member.transactionHash), "duplicate member within or across originals");
      members.add(member.transactionHash);
      requireEvidence(BigInt(member.blockNumber) <= BigInt(input.domain.blockNumber), "preparation follows loading domain");
    }
    requireEvidence(o.evidenceId === claimedSyEvidenceId(input.domain, o, c), "certificate commitment differs");
  }
}

/** Authenticate against the selected RPC, never against self-consistent uploaded receipt JSON. */
export async function authenticateClaimedSy(input: PreparationInput, provider: JsonRpcProvider): Promise<void> {
  const budgets = new Map<string, { historical: bigint; floor: bigint; sy: string }>();
  let snapshotBlock: bigint | undefined;
  const surrender = new Interface([
    "function weightedSySurrender(bytes32) view returns((uint256 consumedUnits,uint256 deliveredCredit,uint256 remainingUnits,uint256 remainingCredit))",
  ]);
  const readAt = async (target: string, method: string, args: readonly unknown[], tag: string) =>
    stakingClaim.decodeFunctionResult(method, hex.parse(await provider.send("eth_call", [
      { to: target, data: stakingClaim.encodeFunctionData(method, args) }, tag,
    ])))[0];
  const codeAt = async (target: string, tag: string) =>
    hex.parse(await provider.send("eth_getCode", [target, tag]));
  for (const row of input.weightedSy) {
    const c = row.claimedOrigin;
    if (!c) continue;
    const wallet = row.original.originalWallet;
    const captured = receipt.parse(await provider.send("eth_getTransactionReceipt", [c.snapshotCapture.transactionHash]));
    const captureHeader = block.parse(await provider.send("eth_getBlockByNumber", [captured.blockNumber, false]));
    const captureEvent = new Interface(["event MigrationSnapshotCaptured(bytes32 indexed snapshotId,uint256 blockNumber)"]);
    const captureLogs = captured.logs.filter((l) => l.address === input.domain.proxy
      && l.topics[0] === captureEvent.getEvent("MigrationSnapshotCaptured")?.topicHash);
    requireEvidence(BigInt(captured.status) === 1n && captured.to === input.domain.proxy
      && captured.transactionHash === c.snapshotCapture.transactionHash
      && captured.blockHash === c.snapshotCapture.blockHash && captureHeader.hash === captured.blockHash
      && BigInt(captured.blockNumber) === BigInt(c.snapshotCapture.blockNumber)
      && BigInt(captured.blockNumber) <= BigInt(input.domain.blockNumber)
      && captureLogs.length === 1 && captureLogs.every((l) => l.transactionHash === captured.transactionHash
        && l.blockHash === captured.blockHash && captureEvent.parseLog({ topics: [...l.topics], data: l.data })?.args[0] === input.domain.snapshotId),
    "snapshot capture is not the authentic canonical domain event");
    requireEvidence(snapshotBlock === undefined || snapshotBlock === BigInt(captured.blockNumber), "different capture domains");
    snapshotBlock = BigInt(captured.blockNumber);
    for (const m of c.members) {
      const tag = `0x${BigInt(m.blockNumber).toString(16)}`;
      const priorTag = `0x${(BigInt(m.blockNumber) - 1n).toString(16)}`;
      const header = block.parse(await provider.send("eth_getBlockByNumber", [tag, false]));
      const prior = block.parse(await provider.send("eth_getBlockByNumber", [priorTag, false]));
      const mined = receipt.parse(await provider.send("eth_getTransactionReceipt", [m.transactionHash]));
      const tx = transaction.parse(await provider.send("eth_getTransactionByHash", [m.transactionHash]));
      const signed = Transaction.from(m.rawSignedTransaction);
      const data = stakingClaim.encodeFunctionData("withdrawClaim", [m.consumedWeight]);
      const relayed = m.execution?.kind === "relayed-eip7702-v1";
      requireEvidence(signed.isSigned() && signed.hash === m.transactionHash
        && signed.chainId === 4663n && signed.value === 0n && signed.authorizationList === null
        && (relayed ? signed.to?.toLowerCase() === wallet
          : signed.from?.toLowerCase() === wallet && signed.to?.toLowerCase() === c.source && signed.data === data),
      "not an admitted signed source or delegated-wallet claim");
      requireEvidence(header.hash === m.blockHash && BigInt(header.number) === BigInt(m.blockNumber)
        && header.parentHash === prior.hash && header.transactions.length === 1
        && header.transactions[0] === m.transactionHash, "noncanonical or nonisolated preparation block");
      requireEvidence(tx.hash === m.transactionHash && tx.from === signed.from?.toLowerCase()
        && tx.to === signed.to?.toLowerCase() && tx.input === signed.data
        && BigInt(tx.value) === 0n && BigInt(tx.chainId) === 4663n
        && tx.blockHash === m.blockHash && tx.blockNumber === header.number && BigInt(tx.transactionIndex) === 0n
        && mined.transactionHash === tx.hash && mined.from === tx.from && mined.to === tx.to
        && mined.blockHash === m.blockHash && mined.blockNumber === header.number
        && BigInt(mined.transactionIndex) === 0n && BigInt(mined.status) === 1n, "transaction or successful receipt differs");
      for (const at of [priorTag, tag]) {
        const walletCode = await codeAt(wallet, at);
        if (m.execution) {
          const delegateCode = await codeAt(m.execution.delegate, at);
          requireEvidence(walletCode === `0xef0100${m.execution.delegate.slice(2)}`
            && delegateCode !== "0x" && keccak256(delegateCode) === m.execution.delegateCodeHash,
          "delegated claimant designation or runtime differs");
        } else requireEvidence(walletCode === "0x", "contract or delegated claimant unsupported");
        for (const [target, selector, facet, runtimeHash] of routes) {
          requireEvidence(keccak256(await codeAt(target, at)) === proxyHash
            && address.parse(await readAt(target, "facetAddress", [selector], at)) === facet
            && keccak256(await codeAt(facet, at)) === runtimeHash, "source runtime or routing differs");
        }
        requireEvidence(await readAt(c.source, "phase", [], at) === 2n
          && address.parse(await readAt(c.source, "claimVault", [], at)) === c.vault
          && address.parse(await readAt(c.vault, "asset", [], at)) === c.sy
          && await readAt(c.vault, "decimals", [], at) === 19n
          && await readAt(c.sy, "decimals", [], at) === 9n, "source phase asset or units differ");
      }
      const collectFrames = (raw: unknown) => {
        const found: z.infer<typeof callFrame>[] = [];
        const pending: unknown[] = [raw];
        while (pending.length) {
          const frame = callFrame.parse(pending.pop());
          requireEvidence(frame.error === undefined, "failed source trace");
          found.push(frame);
          pending.push(...frame.calls);
        }
        return found;
      };
      const frames = collectFrames(await provider.send("debug_traceTransaction", [m.transactionHash, { tracer: "callTracer" }]));
      const sourceFrames = frames.filter((frame) => frame.type === "CALL" && frame.to === c.source
        && frame.input.slice(0, 10) === data.slice(0, 10));
      const sourceFrame = sourceFrames[0];
      requireEvidence(sourceFrames.length === 1 && sourceFrame !== undefined,
      "ambiguous source claim attempts");
      if (m.execution && !relayed) requireEvidence(frames.every((frame) => frame.to !== wallet),
        "direct delegated claim executed claimant wallet code");
      const root = frames[0];
      const output = stakingClaim.encodeFunctionResult("withdrawClaim", [m.receivedSy]);
      const redeemData = stakingClaim.encodeFunctionData("redeem", [m.redeemedVaultShares, wallet, c.source]);
      const redeems = collectFrames(sourceFrame).filter((f) => f.type === "CALL" && f.from === c.source
        && f.to === c.vault && f.input === redeemData && f.output === output);
      requireEvidence(root?.type === "CALL" && root.from === tx.from && root.to === tx.to && root.input === tx.input
        && sourceFrame.from === wallet && sourceFrame.input === data && sourceFrame.output === output
        && redeems.length === 1, "actual source caller, return or vault recipient differs");
      for (const event of mined.logs) {
        requireEvidence(event.transactionHash === m.transactionHash && event.blockHash === m.blockHash
          && event.blockNumber === header.number && BigInt(event.transactionIndex) === 0n, "noncanonical log");
      }
      const claims = mined.logs.filter((l) => l.address === c.source).map((l) =>
        stakingClaim.parseLog({ topics: [...l.topics], data: l.data })).filter((l) => l?.name === "ClaimWithdrawn");
      requireEvidence(claims.length === 1 && address.parse(claims[0]?.args[0]) === wallet
        && claims[0]?.args[1] === BigInt(m.consumedWeight)
        && claims[0]?.args[2] === BigInt(m.receivedSy), "claim event differs");
      const books = async (at: string) => {
        const n = async (target: string, method: string, args: readonly unknown[] = []) =>
          z.bigint().parse(await readAt(target, method, args, at));
        return { weight: await n(c.source, "balanceOf", [wallet]), supply: await n(c.source, "totalSupply"),
          shares: await n(c.vault, "balanceOf", [c.source]), vaultSupply: await n(c.vault, "totalSupply"),
          sy: await n(c.sy, "balanceOf", [wallet]), vaultSy: await n(c.sy, "balanceOf", [c.vault]),
          sySupply: await n(c.sy, "totalSupply") };
      };
      const before = await books(priorTag);
      const after = await books(tag);
      requireEvidence(before.weight - after.weight === BigInt(m.consumedWeight)
        && before.supply - after.supply === BigInt(m.consumedWeight)
        && before.shares - after.shares === BigInt(m.redeemedVaultShares)
        && before.vaultSupply - after.vaultSupply === BigInt(m.redeemedVaultShares)
        && after.sy - before.sy === BigInt(m.receivedSy)
        && before.vaultSy - after.vaultSy === BigInt(m.receivedSy)
        && before.sySupply === after.sySupply, "actual source weight vault or measured SY delta differs");
      requireEvidence(after.weight >= BigInt(c.review.unrelatedWeightFloor)
        && before.sy >= BigInt(c.review.unrelatedSyFloor), "excluded unrelated budget was consumed");
      requireEvidence(block.parse(await provider.send("eth_getBlockByNumber", [tag, false])).hash === header.hash,
        "preparation block changed during authentication");
    }
    const consumed = z.bigint().parse(surrender.decodeFunctionResult("weightedSySurrender",
      hex.parse(await provider.send("eth_call", [{ to: input.domain.proxy,
        data: surrender.encodeFunctionData("weightedSySurrender", [row.original.originalId]) }, "latest"])))[0][0]);
    const q0 = BigInt(row.original.originalUnits);
    requireEvidence(consumed <= q0, "already consumed SY exceeds certified original");
    const previous = budgets.get(wallet) ?? { historical: 0n, floor: 0n, sy: c.sy };
    const excluded = BigInt(c.review.unrelatedSyFloor);
    budgets.set(wallet, { historical: previous.historical + q0,
      floor: previous.floor > excluded ? previous.floor : excluded, sy: c.sy });
  }
  for (const [wallet, budget] of budgets) {
    const historical = z.bigint().parse(await readAt(budget.sy, "balanceOf", [wallet],
      `0x${BigInt(input.domain.blockNumber).toString(16)}`));
    // Certify preparation at its pinned block. Later transfers neither invalidate
    // configuration nor veto owner activation; surrender enforces actual custody.
    requireEvidence(historical >= budget.historical + budget.floor,
      "complete measured descendants or excluded floors were not controlled at preparation");
  }
  if (input.weightedSy.some((row) => row.claimedOrigin)) {
    // Loading never deletes an origin. A later manifest must retain the complete
    // configured SY census, so omitting an earlier original cannot hide its members.
    const configured = new Interface([
      "event WeightedSyEntitlementConfigured(bytes32 indexed originalId,bytes32 indexed configurationId,address indexed originalWallet,uint256 originalUnits,uint256 credit)",
    ]);
    const event = configured.getEvent("WeightedSyEntitlementConfigured");
    requireEvidence(event !== null, "missing configuration event ABI");
    if (snapshotBlock === undefined) throw new PreparationError("PROVENANCE", "missing authenticated capture block");
    const observed = z.array(log).parse(await provider.send("eth_getLogs", [{
      address: input.domain.proxy, fromBlock: `0x${snapshotBlock.toString(16)}`, toBlock: "latest",
      topics: [event?.topicHash],
    }]));
    for (const entry of observed) {
      const decoded = configured.parseLog({ topics: [...entry.topics], data: entry.data });
      requireEvidence(input.weightedSy.some((row) => row.original.originalId === decoded?.args[0]),
        "previously configured SY origin omitted from complete census");
      requireEvidence(block.parse(await provider.send("eth_getBlockByNumber", [entry.blockNumber, false])).hash === entry.blockHash,
        "noncanonical prior configuration");
    }
  }
}

import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { Interface, Result, keccak256 } from "ethers";
import { z } from "zod";
import { canonical, fingerprint } from "./provenance.js";
import { validateManifest } from "./preparation.js";
import { address, hex } from "./schema.js";
import { ExecutionError, executionManifest } from "./execution-schema.js";
import type { ExecutionManifest } from "./execution-schema.js";
import type { Rpc } from "./execution-rpc.js";
import { loadSavedBundle } from "./bundle.js";

export const registryAbi = new Interface(["function vaultsOfPackage(address) view returns (address[])"]);
export const loupeAbi = new Interface([
  "function facetAddress(bytes4) view returns (address)",
  "function facets() view returns ((address facetAddress,bytes4[] functionSelectors)[])",
]);

export async function loadExecution(path: string) {
  const manifest = executionManifest.parse(JSON.parse(await readFile(resolve(path), "utf8")));
  if (manifest.bundle) {
    const saved = await loadSavedBundle(manifest.bundle.path, manifest.bundle);
    if (saved.kind !== "execution"
      || canonical(manifest) !== canonical({ ...saved.execution, preparedManifest: manifest.preparedManifest })
      || Boolean(saved.prepared) !== Boolean(manifest.preparedManifest)) {
      throw new ExecutionError("DOMAIN", "materialized execution differs from saved template");
    }
  }
  for (const source of manifest.sources) {
    if (!source.path.startsWith("/")) throw new ExecutionError("DOMAIN", "execution source paths must be absolute");
    const bytes = await readFile(source.path);
    if (fingerprint(bytes) !== source.sha256 || String(bytes.length) !== source.bytes) {
      throw new ExecutionError("DOMAIN", `source binding differs: ${source.id}`);
    }
  }
  const prepared = manifest.preparedManifest ? await validateManifest(manifest.preparedManifest) : undefined;
  if (manifest.bundle && prepared && canonical(prepared.input.bundle) !== canonical(manifest.bundle)) {
    throw new ExecutionError("DOMAIN", "execution and preparation bundles differ");
  }
  if (prepared && (prepared.input.domain.chainId !== manifest.chainId
    || prepared.input.domain.proxy !== manifest.proxy || prepared.input.domain.snapshotId !== manifest.snapshotId
    || prepared.input.purpose !== manifest.purpose || prepared.input.domain.rpcEnv !== manifest.rpcEnv
    || canonical(prepared.input.domain.bindings) !== canonical([...manifest.bindings].sort(
      (a, b) => a.role.localeCompare(b.role) || a.address.localeCompare(b.address))))) {
    throw new ExecutionError("DOMAIN", "preparation and execution domains disagree");
  }
  if (!prepared && manifest.snapshotId) throw new ExecutionError("DOMAIN", "snapshot requires validated preparation");
  const artifact = async (name: string) => {
    const item = manifest.sources.find((s) => s.id === name);
    if (!item) throw new ExecutionError("DOMAIN", `missing bound ABI artifact ${name}`);
    const value = z.object({ abi: z.array(z.unknown()) }).parse(JSON.parse(await readFile(item.path, "utf8")));
    return new Interface(JSON.stringify(value.abi));
  };
  const migration = await artifact("migration-abi");
  const allocation = await artifact("allocation-abi");
  const recovery = await artifact("recovery-abi");
  const pkg = await artifact("package-abi");
  const syPackage = await artifact("sy-package-abi");
  return { manifest, prepared, abis: { migration, allocation, recovery, pkg, syPackage },
    domain: { manifest, preparedHash: prepared?.normalizedHash ?? null, payloadHash: prepared?.payloadHash ?? null } };
}
export type ExecutionDomain = Awaited<ReturnType<typeof loadExecution>>;

export async function checkRelationships(rpc: Rpc, domain: ExecutionDomain, allowUndeployed: boolean): Promise<void> {
  const m = domain.manifest;
  for (const role of ["proxy", "registry", "package", "facet"] as const) {
    const bindings = m.bindings.filter((b) => b.role === role);
    if (bindings.length === 0 || (role !== "facet" && bindings.length !== 1)) {
      throw new ExecutionError("DOMAIN", `missing or ambiguous ${role} identity`);
    }
  }
  for (const binding of m.bindings) {
    if (binding.role !== "facet" && binding.address !== m[binding.role]) throw new ExecutionError("DOMAIN", "wrong role address");
    const code = hex.parse(await rpc.send("eth_getCode", [binding.address, "latest"]));
    if (allowUndeployed && binding.role === "proxy" && code === "0x") continue;
    if (code === "0x" || keccak256(code) !== binding.codeHash) throw new ExecutionError("DOMAIN", `${binding.role} runtime changed`);
  }
  if (allowUndeployed && hex.parse(await rpc.send("eth_getCode", [m.proxy, "latest"])) === "0x") return;
  const registered = z.array(address).parse((await rpc.call(m.registry, registryAbi, "vaultsOfPackage", [m.package]))[0]);
  if (!registered.includes(m.proxy)) throw new ExecutionError("DOMAIN", "proxy is not registered under bound package");
  const facets: unknown = (await rpc.call(m.proxy, loupeAbi, "facets"))[0];
  const rows = z.array(z.tuple([address, z.array(z.string())])).parse(facets);
  for (const [facet] of rows) {
    if (!m.bindings.some((b) => b.role === "facet" && b.address === facet)) {
      throw new ExecutionError("DOMAIN", "installed facet not in reviewed bindings");
    }
  }
  const activated = (await rpc.call(m.proxy, domain.abis.migration, "migrationActivated"))[0] === true;
  const cuts: unknown = (await rpc.call(m.package, new Interface([
    "function facetCuts() view returns((address facetAddress,uint8 action,bytes4[] functionSelectors)[])",
  ]), "facetCuts"))[0];
  if (!Array.isArray(cuts)) throw new ExecutionError("DOMAIN", "invalid package cuts");
  for (const raw of cuts) {
    if (!(raw instanceof Result)) throw new ExecutionError("DOMAIN", "invalid facet cut");
    const expected = address.parse(raw.getValue("facetAddress"));
    for (const selector of z.array(z.string()).parse(raw.getValue("functionSelectors"))) {
      const removable = domain.abis.allocation.getFunction(selector) !== null;
      const actual = String((await rpc.call(m.proxy, loupeAbi, "facetAddress", [selector]))[0]).toLowerCase();
      if (actual !== (activated && removable ? "0x0000000000000000000000000000000000000000" : expected)) {
        throw new ExecutionError("DOMAIN", "installed selector differs from bound package");
      }
    }
  }
  if (m.snapshotId) {
    const snapshot = await rpc.call(m.proxy, domain.abis.migration, "migrationSnapshot");
    if (snapshot[0].id !== m.snapshotId) throw new ExecutionError("DOMAIN", "current snapshot changed");
  }
}

export function requirePrepared(domain: ExecutionDomain) {
  if (!domain.prepared) throw new ExecutionError("DOMAIN", "stage requires actual post-capture preparation");
  return domain.prepared;
}

import { Interface } from "ethers";
import { canonical, fingerprint } from "./provenance.js";
import { requirePrepared } from "./execution-domain.js";
import type { ExecutionDomain } from "./execution-domain.js";
import { assertNever } from "./execution-rpc.js";
import { ExecutionError } from "./execution-schema.js";
import type { Operation, Stage } from "./execution-schema.js";

export const erc20Abi = new Interface([
  "function approve(address,uint256) returns (bool)",
  "function allowance(address,address) view returns (uint256)",
  "function balanceOf(address) view returns (uint256)",
  "function totalSupply() view returns (uint256)",
]);
export function plan(domain: ExecutionDomain, stage: Stage): readonly Operation[] {
  const { manifest: m, abis } = domain;
  const operations: Operation[] = [];
  const add = (method: string, args: readonly unknown[], iface = abis.allocation, to = m.proxy, value = "0") => {
    const transaction = { from: m.signer, to, data: iface.encodeFunctionData(method, args), value };
    operations.push({ id: fingerprint(canonical({ stage, method, transaction })), stage, method, transaction });
  };
  switch (stage) {
    case "deploy":
      if (!m.deployment) throw new ExecutionError("DOMAIN", "deploy requires complete typed package arguments");
      add("prepareSyChildren", [m.deployment], abis.pkg, m.package);
      add("deployVault", [m.deployment], abis.pkg, m.package);
      break;
    case "fund":
      if (new Set(m.funding.donations.map((r) => r.id)).size !== m.funding.donations.length) {
        throw new ExecutionError("DOMAIN", "duplicate funding identity");
      }
      for (const donation of m.funding.donations) {
        if (donation.tokens.length !== donation.amounts.length
          || new Set(donation.tokens).size !== donation.tokens.length) throw new ExecutionError("DOMAIN", "invalid donation token amounts");
        for (const [i, token] of donation.tokens.entries()) {
          const amount = donation.amounts[i];
          if (!amount) throw new ExecutionError("DOMAIN", "missing donation amount");
          add("approve", [m.proxy, amount], erc20Abi, token);
          const approval = operations.pop();
          if (!approval) throw new ExecutionError("DOMAIN", "missing approval plan");
          operations.push({ ...approval, id: fingerprint(canonical({ donation: donation.id, token, transaction: approval.transaction })) });
        }
        add("donateMigrationCapital", [donation.tokens, donation.amounts, donation.nativeAmount, donation.minimum,
          donation.deadline], abis.migration, m.proxy, donation.nativeAmount);
        // Distinct intentional donations must remain distinct even with equal values.
        const last = operations.pop();
        if (!last) throw new ExecutionError("DOMAIN", "missing donation plan");
        operations.push({ ...last, id: fingerprint(canonical({ id: donation.id, transaction: last.transaction })) });
      }
      if (m.funding.genesis) {
        const g = m.funding.genesis;
        add("bootstrapMigrationReserve", [g.legs, g.anchorIndex, g.minimum, g.deadline]);
      }
      if (!operations.length) throw new ExecutionError("DOMAIN", "no funding operation selected");
      break;
    case "capture": add("captureMigrationSnapshot", []); break;
    case "configure": {
      const p = requirePrepared(domain);
      for (const row of p.payloads.configure.independent) add("configureIndependentAllocations", [[row.input]]);
      for (const row of p.payloads.configure.nfts) {
        add(row.input.separateContributions ? "configureNftContributionEntitlements" : "configureNftEntitlements", [[row.input]]);
      }
      for (const row of p.payloads.configure.weightedLiquid) add("configureWeightedLiquidEntitlements", [[row.input]]);
      for (const row of p.payloads.configure.weightedSy) {
        if (row.input.claimBasis) {
          add("configureClaimedSyEntitlements", [[{ original: row.input, ...row.input.claimBasis }]]);
        } else add("configureWeightedSyEntitlements", [[row.input]]);
      }
      for (const row of p.payloads.configure.dtfCustodySe) add("configureDtfCustodySeEntitlements", [[row.input]]);
      for (const row of p.payloads.configure.claimVault) add("configureClaimVaultEntitlements", [[row.input]]);
      for (const row of p.payloads.configure.weightedReceipt) add("configureWeightedReceiptEntitlements", [[row.input]]);
      for (const row of p.payloads.configure.earlierLiquid) add("configureEarlierLiquidEntitlements", [[row.input]]);
      for (const row of p.payloads.configure.heldSeLp) add("configureHeldSeLpEntitlements", [[row.input]]);
      for (const row of p.payloads.configure.earlierReceipt) add("configureEarlierReceiptEntitlements", [[row.input]]);
      if (!operations.length) throw new ExecutionError("DOMAIN", "no supported configuration selected");
      break;
    }
    case "independent-issue":
      for (const row of requirePrepared(domain).payloads.independentIssue.requests) add("issueIndependentAllocations", [[row]]);
      if (!operations.length) throw new ExecutionError("DOMAIN", "no independent issuance selected");
      break;
    case "owner-bond": {
      requirePrepared(domain);
      const purchase = m.ownerBond;
      if (!purchase) throw new ExecutionError("DOMAIN", "owner-bond requires explicit payment, duration and deadline");
      add("approve", [m.proxy, purchase.amount], erc20Abi, purchase.token);
      add("bond", [purchase.token, purchase.amount, purchase.duration, m.signer, false, purchase.deadline], abis.migration);
      break;
    }
    case "activate": requirePrepared(domain); add("activateMigration", []); break;
    case "harvest": {
      const h = requirePrepared(domain).payloads.harvest;
      if (!h.steps.length) throw new ExecutionError("DOMAIN", "no admitted recovery step selected");
      const names = ["WeightedClaim", "WeightedPrincipal", "WeightedRewards", "WeightedUnstake",
        "WeightedConvert", "EarlierClaim", "EarlierSale", "Donate", "WeightedSyRedeem", "DtfCustodySeRedeem", "ClaimVaultRedeem"] as const;
      add("recoverMigrationNfts", [h.steps.map((s) => ({ ...s, stage: names.indexOf(s.stage) })), h.deadline], abis.recovery);
      break;
    }
    case "verify": requirePrepared(domain); break;
    default: assertNever(stage);
  }
  return operations;
}

import { z } from "zod";
