  const metadata = z.object({
    instanceId: z.string(), forkedNetwork: z.object({ forkBlockNumber: z.number().int().safe(), forkBlockHash: hash }).passthrough(),
  }).passthrough().parse(await chain.send("anvil_metadata", []));
