  const generated = z.object({ transactions: z.array(z.object({ transaction: z.object({
    from: address, to: address.nullable().optional(), input: hex, value: quantity.default("0x0"), nonce: quantity,
  }).passthrough() }).passthrough()) }).passthrough().parse(JSON.parse(await readFile(
    "broadcast/MigrationDeploymentGasResumedQA.s.sol/4663/dry-run/run-latest.json", "utf8")));
  const wallet = Wallet.fromPhrase("test test test test test test test test test test test junk");
  const pkg = await interfaceFile("out/IUniswapV4DetfMigrationDFPkg.sol/IUniswapV4DetfMigrationDFPkg.json");
  const migration = await interfaceFile("out/IUniswapV4DetfMigration.sol/IUniswapV4DetfMigration.json");
  const records = [];
  const constrained = [];
  const parents = new Set<string>();
  const owners = new Set<string>();
  const preparationSelector = pkg.getFunction("prepareSyChildren")?.selector;
  const finalSelector = pkg.getFunction("deployVault")?.selector;
  for (const [index, entry] of generated.transactions.entries()) {
    const tx = entry.transaction;
    if (tx.from !== DEV || BigInt(tx.nonce) > BigInt(Number.MAX_SAFE_INTEGER)) throw new Error("unexpected fixture signer/nonce");
    const request = { from: DEV, ...(tx.to ? { to: tx.to } : {}), data: tx.input, value: tx.value,
      gas: "0x1e84800", gasPrice: "0x77359400" };
    await chain.send("eth_call", [request, "latest"]);
    const raw = await wallet.signTransaction({ ...(tx.to ? { to: tx.to } : {}),
      data: tx.input, value: BigInt(tx.value), nonce: Number(BigInt(tx.nonce)), chainId: 4663n,
      gasLimit: 32_000_000n, gasPrice: 2_000_000_000n, type: 0 });
    const transactionHash = keccak256(raw);
    const watch = await subscribeReceipt(chain, transactionHash);
    try {
      if (await chain.send("eth_sendRawTransaction", [raw]) !== transactionHash) throw new Error("submitted hash differs");
      await chain.send("evm_mine", []);
      const receipt = await watch.mined();
      const actual = z.object({ gas: quantity, hash, blockHash: hash }).passthrough().parse(
        await chain.send("eth_getTransactionByHash", [transactionHash]));
      if (BigInt(receipt.status) !== 1n || actual.hash !== transactionHash
        || actual.blockHash !== receipt.blockHash || BigInt(actual.gas) !== 32_000_000n) {
        throw new Error(`bounded transaction ${index} failed`);
      }
      const record = { index, transactionHash, rawSignedTransaction: raw, transaction: actual, receipt };
      records.push(record);
      if (tx.to && (tx.input.slice(0, 10) === preparationSelector || tx.input.slice(0, 10) === finalSelector)) {
        const method = tx.input.slice(0, 10) === preparationSelector ? "prepareSyChildren" : "deployVault";
        const args = pkg.decodeFunctionData(method, tx.input)[0];
        const construction = (await chain.call(tx.to, pkg, "syConstruction", [args]))[0];
        const parent = address.parse(construction.parent);
        if (method === "prepareSyChildren") {
          if (await chain.send("eth_getCode", [parent, "latest"]) !== "0x") throw new Error("preparation published parent");
        } else {
          if (address.parse((await chain.call(parent, migration, "owner"))[0]) !== address.parse(args.owner)
            || (await chain.call(parent, migration, "migrationActivated"))[0] !== false
            || (await chain.call(parent, new Interface(["function totalSupply() view returns(uint256)"]), "totalSupply"))[0] !== 0n) {
            throw new Error("final parent identity or initial state differs");
          }
          parents.add(parent);
          owners.add(address.parse(args.owner));
        }
        constrained.push({ method, parent, transactionHash, envelope: BigInt(actual.gas).toString(),
          gasUsed: BigInt(quantity.parse(receipt["gasUsed"])).toString() });
      }
    } finally { watch.close(); }
    if (index % 50 === 0) console.log(`BOUNDED_TX ${index + 1}/${generated.transactions.length}`);
  }
  if (constrained.length !== 4 || parents.size !== 2 || owners.size !== 2) throw new Error("two distinct constructions not demonstrated");
  await save(join(evidence, "transactions.json"), records);
  await save(join(evidence, "constrained-receipts.json"), constrained);
  console.log(JSON.stringify({ status: "two-bounded-deployments-pass", transactions: records.length, constrained }));
} finally {
  chain.close();
  await node.close();
  await save(join(evidence, "cleanup.json"), { node: "exited", port: 18561 });
}

import { join } from "node:path";
import { readFile } from "node:fs/promises";
import { z } from "zod";
import { claimedSyEvidenceId } from "./claimed-sy.js";
import { claimedWallet } from "./rehearsal-claimed-sy-source.js";
import { save, sourceFile } from "./rehearsal-data.js";
import { prepareDomain } from "./preparation.js";
import { claimedSyCertificate, PreparationError, preparationInput } from "./schema.js";
import type { PreparationInput } from "./schema.js";
import { ExecutionError } from "./execution-schema.js";
import { DEV } from "./execution-rpc.js";
import type { RehearsalChain } from "./rehearsal-chain.js";

/** Reconcile the real gate before any configuration transaction, not only a schema mock. */
export async function checkClaimedSyIntake(chain: RehearsalChain, input: PreparationInput, evidence: string) {
  const selected = input.weightedSy.filter((row) => row.claimedOrigin);
  const first = selected[0];
  const second = selected[1];
  if (!first?.claimedOrigin || !second?.claimedOrigin) throw new ExecutionError("STATE", "two complete originals required");
  const delegated = selected.find((row) => row.claimedOrigin?.members.some((member) => member.execution));
  if (!delegated?.claimedOrigin) throw new ExecutionError("STATE", "delegated source witness required");
  const nonce = await chain.send("eth_getTransactionCount", [DEV, "latest"]);
  const cases: { readonly name: string; readonly row: PreparationInput["weightedSy"][number]; readonly certificate: unknown }[] = [
    { name: "incomplete", certificate: { ...second.claimedOrigin, members: second.claimedOrigin.members.slice(0, -1) } },
    { name: "duplicate", certificate: { ...second.claimedOrigin,
      members: second.claimedOrigin.members.map((m) => ({ ...m, transactionHash: second.claimedOrigin?.members[0]?.transactionHash })) } },
    { name: "wrong-output", certificate: { ...second.claimedOrigin,
      members: second.claimedOrigin.members.map((m, i) => i === 0 ? { ...m, receivedSy: String(BigInt(m.receivedSy) + 1n) } : m) } },
    { name: "noncanonical", certificate: { ...second.claimedOrigin,
      members: second.claimedOrigin.members.map((m) => ({ ...m, blockHash: `0x${"f".repeat(64)}` })) } },
    { name: "tampered-signature", certificate: { ...second.claimedOrigin,
      members: second.claimedOrigin.members.map((m) => ({ ...m, rawSignedTransaction: first.claimedOrigin?.members[0]?.rawSignedTransaction })) } },
  ].map((test) => ({ ...test, row: second }));
  cases.push(
    { name: "missing-delegation", row: delegated, certificate: { ...delegated.claimedOrigin,
      members: delegated.claimedOrigin.members.map(({ execution: _execution, ...member }) => member) } },
    { name: "wrong-delegate-runtime", row: delegated, certificate: { ...delegated.claimedOrigin,
      members: delegated.claimedOrigin.members.map((member) => ({ ...member,
        execution: { ...member.execution, delegateCodeHash: `0x${"f".repeat(64)}` } })) } },
  );
  const relayed = selected.find((row) => row.original.originalWallet === claimedWallet(236).address.toLowerCase());
  if (!relayed?.claimedOrigin || relayed.claimedOrigin.members.length !== 1) {
    throw new ExecutionError("STATE", "single-member relayed source witness required");
  }
  const relayNegatives = z.array(z.object({
    kind: z.string(), transactionHash: z.string(), rawSignedTransaction: z.string(),
    blockNumber: z.string(), blockHash: z.string(),
  })).parse(JSON.parse(await readFile(join(evidence, "claimed-relay-negatives-236.json"), "utf8")));
  for (const negative of relayNegatives) {
    const { kind, ...transaction } = negative;
    cases.push({ name: `relayed-${kind}`, row: relayed, certificate: { ...relayed.claimedOrigin,
      members: relayed.claimedOrigin.members.map((member) => ({ ...member, ...transaction })) } });
  }
  cases.push({ name: "relayed-as-direct", row: relayed, certificate: { ...relayed.claimedOrigin,
    members: relayed.claimedOrigin.members.map((member) => ({ ...member,
      execution: { ...member.execution, kind: "direct-eip7702-v1" } })) } });
  const observations = [];
  for (const test of cases) {
    const certificate = claimedSyCertificate.parse(test.certificate);
    const original = { ...test.row.original, evidenceId: claimedSyEvidenceId(input.domain, test.row.original, certificate) };
    const changed = { original, claimedOrigin: certificate };
    const path = join(evidence, `claimed-intake-${test.name}.json`);
    await save(path, changed);
    const candidate = preparationInput.parse({ ...input,
      sources: [...input.sources, await sourceFile(`claimed-negative-${test.name}`, path)],
      weightedSy: input.weightedSy.map((row) => row.original.originalId === original.originalId
        ? { ...changed, proof: { sourceId: `claimed-negative-${test.name}`, pointer: "" } } : row),
    });
    let rejected = false;
    try { await prepareDomain(candidate); }
    catch (error) {
      if (!(error instanceof PreparationError)) throw error;
      observations.push({ case: test.name, code: error.code, reason: error.message });
      rejected = true;
    }
    if (!rejected) throw new ExecutionError("STATE", `claimed intake ${test.name} unexpectedly passed`);
  }
  const { claimedOrigin: _missing, ...ordinary } = second;
  const flatIndex = input.weightedSy.findIndex(row => row.original.originalId === second.original.originalId);
  for (const [name, pointer] of [
    ["missing-certificate", ordinary.proof.pointer],
    ["nested-proof-downgrade", `${ordinary.proof.pointer}/original`],
    ["flat-proof-downgrade", `/weightedSy/${flatIndex}`],
  ]) {
    const candidate = preparationInput.parse({ ...input, weightedSy: input.weightedSy.map((row) =>
      row.original.originalId === second.original.originalId
        ? { ...ordinary, proof: { ...ordinary.proof, pointer } } : row) });
    try {
      await prepareDomain(candidate);
      throw new ExecutionError("STATE", "missing claimed evidence fell back to ordinary SY");
    } catch (error) {
      if (!(error instanceof PreparationError) || error.code !== "PROVENANCE") throw error;
      observations.push({ case: name, code: error.code, reason: error.message });
    }
  }
  if (nonce !== await chain.send("eth_getTransactionCount", [DEV, "latest"])) {
    throw new ExecutionError("STATE", "claimed intake rejection broadcast a configuration");
  }
  await save(join(evidence, "claimed-intake-rejections.json"), { nonceBefore: nonce, nonceAfter: nonce, observations });
}

import { Interface } from "ethers";
import { join } from "node:path";
import { z } from "zod";
import { claimedSigned, claimedWallet } from "./rehearsal-claimed-sy-source.js";
import { interfaceFile, save } from "./rehearsal-data.js";
import type { RehearsalChain } from "./rehearsal-chain.js";
import type { PreparationInput } from "./schema.js";
import type { ExecutionManifest } from "./execution-schema.js";
import { ExecutionError } from "./execution-schema.js";

/** A configured holder's later transfer cannot veto the owner's activation. */
export async function exerciseClaimedSyTransfer(context: {
  readonly chain: RehearsalChain; readonly input: PreparationInput;
  readonly manifest: ExecutionManifest; readonly evidence: string;
  readonly activate: () => Promise<void>;
}) {
  const { chain, input, manifest, evidence } = context;
  const wallet = claimedWallet(231).address.toLowerCase();
  const recipient = claimedWallet(239).address.toLowerCase();
  const row = input.weightedSy.find((item) => item.claimedOrigin && item.original.originalWallet === wallet);
  if (!row) throw new ExecutionError("STATE", "controlled claimed original required");
  const token = new Interface([
    "function transfer(address,uint256) returns(bool)",
    "function balanceOf(address) view returns(uint256)",
    "function totalSupply() view returns(uint256)",
  ]);
  const migration = await interfaceFile("out/IUniswapV4DetfMigration.sol/IUniswapV4DetfMigration.json");
  const sy = row.original.source;
  const amount = row.original.originalUnits;
  const balance = async (account: string) => z.bigint().parse((await chain.call(sy, token, "balanceOf", [account]))[0]);
  if (await chain.send("eth_getCode", [recipient, "latest"]) !== "0x" || await balance(recipient) !== 0n) {
    throw new ExecutionError("STATE", "transfer recipient must be a fresh controlled account");
  }
  await claimedSigned(chain, evidence, { index: 0, to: recipient, data: "0x", value: 10n ** 18n });
  const original = (await chain.call(manifest.proxy, migration, "weightedSyEntitlement", [row.original.originalId])).toString();
  const away = await claimedSigned(chain, evidence, { index: 231, to: sy,
    data: token.encodeFunctionData("transfer", [recipient, amount]) });
  await context.activate();
  const ledger = async () => (await chain.call(manifest.proxy, migration, "weightedSySurrender", [row.original.originalId])).toString();
  const before = await ledger();
  const supply = (await chain.call(manifest.proxy, token, "totalSupply"))[0];
  const custody = await balance(manifest.proxy);
  const failed = await claimedSigned(chain, evidence, { index: 231, to: manifest.proxy, status: 0n,
    data: migration.encodeFunctionData("surrenderMigrationWeightedSy",
      [row.original.originalId, amount, 0, await chain.timestamp() + 3600n]) });
  if (await ledger() !== before || (await chain.call(manifest.proxy, token, "totalSupply"))[0] !== supply
    || await balance(manifest.proxy) !== custody) {
    throw new ExecutionError("STATE", "absent claimed assets changed credit or custody");
  }
  const returned = await claimedSigned(chain, evidence, { index: 239, to: sy,
    data: token.encodeFunctionData("transfer", [wallet, amount]) });
  if (await balance(recipient) !== 0n || original !==
    (await chain.call(manifest.proxy, migration, "weightedSyEntitlement", [row.original.originalId])).toString()) {
    throw new ExecutionError("STATE", "transfer/return changed configured original");
  }
  await save(join(evidence, "claimed-holder-transfer-activation.json"), {
    originalId: row.original.originalId, originalWallet: wallet, recipient, amount,
    transfer: away.mined.transactionHash, failedSurrender: failed.mined.transactionHash,
    returned: returned.mined.transactionHash, configurationUnchanged: true,
    activationWhileAssetsAway: (await chain.call(manifest.proxy, migration, "migrationActivated"))[0],
  });
}
